-- Migration 0001: cloud-save storage.
--
-- Activated in M4/M5. Types are kept portable (TEXT/INTEGER/TIMESTAMP) so moving
-- to Postgres later is a schema review, not a rewrite. Ids are opaque strings
-- generated by the application, not database sequences.

CREATE TABLE IF NOT EXISTS device_accounts (
    id         TEXT PRIMARY KEY,                        -- opaque device id (auth stub, M5)
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS saves (
    device_id      TEXT NOT NULL REFERENCES device_accounts(id),
    slot           INTEGER NOT NULL,
    schema_version INTEGER NOT NULL,                    -- mirrors the save blob's schema_version
    payload        TEXT NOT NULL,                       -- self-contained versioned JSON save blob
    updated_at     TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,  -- last-write-wins tiebreaker
    PRIMARY KEY (device_id, slot)
);
